import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data.csv')
df['hist']=np.exp(df.log_hist_days)
# placebo with flexible controls
specs = {
 'lin': 'log_hist_days + C(region) + log_pre_gmv + orders + cat_share + tenure + C(tier)',
 'hist': 'hist + log_hist_days + C(region) + log_pre_gmv + orders + cat_share + tenure + C(tier)',
 'hist_int': 'hist*C(region) + log_hist_days*C(region) + log_pre_gmv + orders + cat_share + tenure + C(tier) + log_pre_gmv*C(region)',
}
for k,v in specs.items():
    for out in ['dY','dY_placebo']:
        m = smf.ols(f'{out} ~ D + {v}', data=df).fit(cov_type='HC1')
        print(k, out, 'D=%.4f (%.4f)'%(m.params['D'], m.bse['D']))
